});

/** @jest-environment node */
import { TASK_LIMITS, TASK_REDACTED } from '@/types';
import {
  deciderOk,
  makeCompletionDecision,
  makeElement,
  makeObservation,
} from './helpers/agent-fixtures';
import { requireStatus, setup, terminal } from './helpers/task-agent-contract';

const lateMarker = 'REVIEW_DETAILS_AFTER_THE_LABEL_LIMIT';
const longText = (cap: number): string => `${'a'.repeat(300)}${lateMarker}${'b'.repeat(cap)}`;
const passage = (text: string) =>
  makeElement({
    id: 't7',
    role: 'paragraph',
    kind: 'passage',
    label: 'Order review',
    text,
    operations: ['READ'],
  });

describe('coordinator observation text uses its field contract cap', () => {
  test('page text past the label cap reaches both action and independent completion requests up to observedTextChars', async () => {
    const text = longText(TASK_LIMITS.observedTextChars);
    const { agent, fakeDecider } = setup(
      {
        chooseAction: [deciderOk('action', terminal('DONE'))],
        verifyCompletion: [
          deciderOk('completion', makeCompletionDecision({ evidenceTargetIds: ['t7'] })),
        ],
      },
      { observations: [makeObservation({ text, elements: [passage('Observed review evidence')] })] }
    );
    requireStatus(await agent.run({ goal: 'Inspect the observed order review.' }), 'completed');
    const actionText = fakeDecider.calls.chooseAction[0]?.request.observation.text ?? '';
    const verificationText = fakeDecider.calls.verifyCompletion[0]?.request.observation.text ?? '';
    expect(Array.from(actionText).length).toBe(TASK_LIMITS.observedTextChars);
    expect(actionText.includes(lateMarker)).toBe(true);
    expect(verificationText === actionText).toBe(true);
  });

  test('reading passage text past the label cap is preserved up to passageChars in both decision stages', async () => {
    const text = longText(TASK_LIMITS.passageChars);
    const { agent, fakeDecider } = setup(
      {
        chooseAction: [deciderOk('action', terminal('DONE'))],
        verifyCompletion: [
          deciderOk('completion', makeCompletionDecision({ evidenceTargetIds: ['t7'] })),
        ],
      },
      { observations: [makeObservation({ elements: [passage(text)] })] }
    );
    requireStatus(await agent.run({ goal: 'Inspect the observed reading passage.' }), 'completed');
    const actionText =
      fakeDecider.calls.chooseAction[0]?.request.observation.elements[0]?.text ?? '';
    const verificationText =
      fakeDecider.calls.verifyCompletion[0]?.request.observation.elements[0]?.text ?? '';
    expect(Array.from(actionText).length).toBe(TASK_LIMITS.passageChars);
    expect(actionText.includes(lateMarker)).toBe(true);
    expect(verificationText === actionText).toBe(true);
  });

  test('long page and passage text retain useful late content while sensitive text is scrubbed before either call', async () => {
    const secret = String.fromCharCode(
      99,
      97,
      112,
      45,
      115,
      101,
      99,
      114,
      101,
      116,
      45,
      55,
      56,
      49
    );
    const text = `${'a'.repeat(300)}${lateMarker} ${secret} ${'b'.repeat(TASK_LIMITS.observedTextChars)}`;
    const { agent, fakeDecider } = setup(
      {
        chooseAction: [deciderOk('action', terminal('DONE'))],
        verifyCompletion: [
          deciderOk('completion', makeCompletionDecision({ evidenceTargetIds: ['t7'] })),
        ],
      },
      { observations: [makeObservation({ text, elements: [passage(text)] })] }
    );
    const result = requireStatus(
      await agent.run({
        goal: 'Inspect the observed review contents.',
        inputs: { password: secret },
        options: { captureTrace: true },
      }),
      'completed'
    );
    const action = fakeDecider.calls.chooseAction[0]?.request.observation;
    const verification = fakeDecider.calls.verifyCompletion[0]?.request.observation;
    for (const observation of [action, verification]) {
      expect(observation?.text.includes(lateMarker)).toBe(true);
      expect(observation?.text.includes(TASK_REDACTED)).toBe(true);
      expect(observation?.text.includes(secret)).toBe(false);
      expect(observation?.elements[0]?.text?.includes(lateMarker)).toBe(true);
      expect(observation?.elements[0]?.text?.includes(TASK_REDACTED)).toBe(true);
      expect(observation?.elements[0]?.text?.includes(secret)).toBe(false);
      expect(Array.from(observation?.text ?? '').length).toBe(TASK_LIMITS.observedTextChars);
      expect(Array.from(observation?.elements[0]?.text ?? '').length).toBe(
        TASK_LIMITS.passageChars
      );
    }
    expect(JSON.stringify(fakeDecider.calls).includes(secret)).toBe(false);
    expect(JSON.stringify(result).includes(secret)).toBe(false);
  });
});

/** @jest-environment node */
import * as progress from '@/agent/progress';
import { createTaskAgent } from '@/agent/TaskAgent';
import type { TaskElementState, TaskObservation, TaskRunOptions } from '@/types';
import {
  deciderOk,
  makeCompletionDecision,
  makeElement,
  makeObservation,
  makePassage,
  makeRequest,
  makeSensitiveField,
  makeTextField,
} from './helpers/agent-fixtures';
import { action, requireStatus, secretValue, setup, terminal } from './helpers/task-agent-contract';

const routine = deciderOk('commitment', {
  commitment: 'NONE' as const,
  confidence: 0.99,
  agreement: 'single' as const,
});
const page = (overrides: Partial<TaskObservation> = {}): TaskObservation =>
  makeObservation({ elements: [makeElement(), makeTextField()], ...overrides });

async function observePair(first: TaskObservation, second: TaskObservation, capture = true) {
  const scenario = setup(
    {
      chooseAction: [deciderOk('action', action('CLICK', 't1'))],
      classifyCommitment: [routine],
    },
    { observations: [first, second] }
  );
  const result = requireStatus(
    await scenario.agent.run(
      makeRequest({ options: { captureProgressDiagnostics: capture, budgets: { maxSteps: 1 } } })
    ),
    'blocked'
  );
  expect(result.reason).toBe('BUDGET_EXHAUSTED');
  expect(scenario.fakeHost.calls.execute).toHaveLength(1);
  return { ...scenario, result };
}

describe('TaskAgent opt-in shadow semantic progress', () => {
  test('counts fresh completion observations while a changing page clock remains cosmetic', async () => {
    const clockPage = (clock: number) =>
      page({
        text: `Clock ${clock}`,
        elements: [makeElement(), makePassage({ text: `${clock}` })],
      });
    const scenario = setup(
      {
        chooseAction: [
          deciderOk('action', action('CLICK', 't1')),
          deciderOk('action', terminal('DONE')),
        ],
        classifyCommitment: [routine],
        verifyCompletion: [deciderOk('completion', makeCompletionDecision())],
      },
      { observations: [clockPage(1), clockPage(2), clockPage(3)] }
    );
    const result = requireStatus(
      await scenario.agent.run(makeRequest({ options: { captureProgressDiagnostics: true } })),
      'completed'
    );
    expect(result.progressDiagnostics).toEqual({
      scope: 'active_segment',
      observations: 3,
      semanticChanges: 0,
      cosmeticOnlyChanges: 2,
      repeatedStates: 2,
      maxUnchangedStreak: 2,
    });
    expect(scenario.fakeDecider.calls.verifyCompletion).toHaveLength(1);
    expect(result.stats.usage.noProgress).toBe(0);
  });

  test('snapshot ids, timestamps, focused state and passage changes do not count as semantic changes', async () => {
    const first = page({ elements: [makeElement(), makePassage()] });
    const second = page({
      snapshotId: 'snap_changed',
      observedAt: first.observedAt + 100,
      title: 'Clock 09:43',
      text: 'Clock 09:43',
      elements: [makeElement({ state: { focused: true } }), makePassage({ text: '09:43' })],
      truncation: { ...first.truncation, textTruncated: true },
    });
    const { result } = await observePair(first, second);
    expect(result.progressDiagnostics).toEqual({
      scope: 'active_segment',
      observations: 2,
      semanticChanges: 0,
      cosmeticOnlyChanges: 1,
      repeatedStates: 1,
      maxUnchangedStreak: 1,
    });
  });

  test.each<Partial<TaskElementState>>([
    { value: 'Updated name' },
    { checked: true },
    { selected: true },
    { expanded: true },
    { pressed: true },
    { disabled: true },
    { readOnly: true },
    { required: true },
    { invalid: true },
    { constraintInvalid: true },
  ])('observes relevant control state %j without changing the execution budget', async state => {
    const { result } = await observePair(
      page(),
      page({ elements: [makeElement(), makeTextField({ state })] })
    );
    expect(result.progressDiagnostics).toEqual({
      scope: 'active_segment',
      observations: 2,
      semanticChanges: 1,
      cosmeticOnlyChanges: 0,
      repeatedStates: 0,
      maxUnchangedStreak: 0,
    });
    expect(result.stats.usage.steps).toBe(1);
  });

  test.each<Partial<TaskObservation>>([
    { documentId: 'doc_changed' },
    { url: 'https://shop.example.test/next' },
    { validation: [{ source: 'native', text: 'Enter your name', targetId: 't3' }] },
    { dialogs: [{ id: 'dialog_1', modal: true, label: 'Confirm', elementIds: ['t1'] }] },
    { elements: [makeElement(), makeTextField({ inViewport: false })] },
    {
      page: {
        ...page().page,
        scroll: { top: 100, max: 200, directions: ['UP', 'DOWN'] },
      },
    },
  ])('tracks navigation, validation, dialog, visibility and scroll facts %j', async change => {
    const { result } = await observePair(page(), page(change));
    expect(result.progressDiagnostics?.semanticChanges).toBe(1);
    expect(result.progressDiagnostics?.observations).toBe(2);
  });

  test('stable control identities survive changed snapshot target ids and element order', async () => {
    const first = page({
      elements: [
        makeElement({ controlId: 'button_node', dialogId: 'dialog_1' }),
        makeTextField({ controlId: 'field_node', dialogId: 'dialog_1' }),
      ],
      validation: [{ source: 'native', text: 'Enter your name', targetId: 't3' }],
      dialogs: [{ id: 'dialog_1', modal: true, label: 'Confirm', elementIds: ['t1', 't3'] }],
    });
    const second = page({
      elements: [
        makeTextField({ id: 'new_field', controlId: 'field_node', dialogId: 'dialog_2' }),
        makeElement({ id: 'new_button', controlId: 'button_node', dialogId: 'dialog_2' }),
      ],
      validation: [{ source: 'native', text: 'Enter your name', targetId: 'new_field' }],
      dialogs: [
        { id: 'dialog_2', modal: true, label: 'Confirm', elementIds: ['new_field', 'new_button'] },
      ],
    });
    const { result } = await observePair(first, second);
    expect(result.progressDiagnostics?.semanticChanges).toBe(0);
    expect(result.progressDiagnostics?.repeatedStates).toBe(1);
  });

  test('existing NO_PROGRESS outcome and counters remain identical with diagnostics enabled', async () => {
    const scenario = (captureProgressDiagnostics: boolean) =>
      setup(
        {
          chooseAction: [
            deciderOk('action', action('CLICK', 't1')),
            deciderOk('action', action('CLICK', 't9')),
          ],
          classifyCommitment: [routine, routine],
        },
        { observations: [page({ elements: [makeElement(), makeElement({ id: 't9' })] })] },
        { run: { captureProgressDiagnostics, budgets: { maxNoProgress: 1 } } }
      );
    const plain = scenario(false);
    const captured = scenario(true);
    const without = requireStatus(await plain.agent.run(makeRequest()), 'blocked');
    const withDiagnostics = requireStatus(await captured.agent.run(makeRequest()), 'blocked');
    expect(without.reason).toBe('NO_PROGRESS');
    const { progressDiagnostics, ...remaining } = withDiagnostics;
    expect(remaining).toEqual(without);
    expect(progressDiagnostics?.observations).toBe(3);
    expect(progressDiagnostics?.maxUnchangedStreak).toBe(2);
    expect(captured.fakeHost.calls.order).toEqual(plain.fakeHost.calls.order);
    expect(captured.fakeHost.calls.execute).toEqual(plain.fakeHost.calls.execute);
  });

  test('default results omit diagnostics and the semantic tracker is not invoked', async () => {
    const trackerFactory = jest.spyOn(progress, 'createProgressTracker');
    const { agent } = setup({}, {}, { run: { budgets: { maxSteps: 0 } } });
    const result = await agent.run(makeRequest());
    expect(result).not.toHaveProperty('progressDiagnostics');
    expect(trackerFactory).not.toHaveBeenCalled();
    trackerFactory.mockRestore();
  });

  test('an instrumentation failure cannot turn a real coordinator completion into failure', async () => {
    const original = progress.createProgressTracker;
    const trackerFactory = jest
      .spyOn(progress, 'createProgressTracker')
      .mockImplementation(maxSteps => ({
        ...original(maxSteps),
        observe: () => {
          throw new Error('diagnostic-only failure');
        },
      }));
    try {
      const scenario = setup({
        chooseAction: [deciderOk('action', terminal('DONE'))],
        verifyCompletion: [deciderOk('completion', makeCompletionDecision())],
      });
      const result = requireStatus(
        await scenario.agent.run(
          makeRequest({
            options: { captureProgressDiagnostics: true },
          })
        ),
        'completed'
      );
      expect(result).not.toHaveProperty('progressDiagnostics');
      expect(scenario.fakeDecider.calls.verifyCompletion).toHaveLength(1);
      expect(scenario.fakeHost.calls.execute).toHaveLength(0);
    } finally {
      trackerFactory.mockRestore();
    }
  });

  test('diagnostics expose only counters and do not distinguish two populated sensitive values', async () => {
    const secret = secretValue();
    const scenario = setup(
      { chooseAction: [deciderOk('action', action('CLICK', 't1'))], classifyCommitment: [routine] },
      {
        observations: [
          page({ elements: [makeElement(), makeSensitiveField({ state: { value: secret } })] }),
          page({
            elements: [
              makeElement(),
              makeSensitiveField({ state: { value: 'other-secret-value' } }),
            ],
          }),
        ],
      }
    );
    const result = await scenario.agent.run(
      makeRequest({
        inputs: { password: secret },
        options: { captureProgressDiagnostics: true, budgets: { maxSteps: 1 } },
      })
    );
    expect(result.progressDiagnostics?.semanticChanges).toBe(0);
    expect(Object.keys(result.progressDiagnostics ?? {}).sort()).toEqual([
      'cosmeticOnlyChanges',
      'maxUnchangedStreak',
      'observations',
      'repeatedStates',
      'scope',
      'semanticChanges',
    ]);
    expect(JSON.stringify(result.progressDiagnostics)).not.toContain(secret);
    expect(JSON.stringify(result.progressDiagnostics)).not.toContain('other-secret-value');
  });

  test('a resumed segment starts a new tracker without checkpoint progress state', async () => {
    const scenario = setup(
      {
        chooseAction: [deciderOk('action', action('FILL', 't3'))],
        chooseArgument: [deciderOk('argument', { kind: 'none_appropriate', confidence: 0.99 })],
      },
      { observations: [page()] }
    );
    const paused = requireStatus(
      await scenario.agent.run(
        makeRequest({ inputs: { name: 'Ada' }, options: { captureProgressDiagnostics: true } })
      ),
      'needs_input'
    );
    expect(paused.progressDiagnostics?.observations).toBe(1);
    expect(paused.checkpoint).not.toHaveProperty('progressDiagnostics');
    const result = requireStatus(
      await scenario.agent.resume({
        checkpoint: paused.checkpoint,
        resolution: { kind: 'inputs', inputs: { name: 'Grace' } },
        options: { budgets: { maxSteps: paused.steps } },
      }),
      'blocked'
    );
    expect(result.progressDiagnostics).toEqual({
      scope: 'active_segment',
      observations: 1,
      semanticChanges: 0,
      cosmeticOnlyChanges: 0,
      repeatedStates: 0,
      maxUnchangedStreak: 0,
    });
  });

  test.each(['request', 'configured', 'resume'] as const)(
    'rejects nonboolean %s flags before any new boundary calls',
    async source => {
      const invalid = { captureProgressDiagnostics: 'yes' } as unknown as TaskRunOptions;
      if (source === 'resume') {
        const scenario = setup(
          {
            chooseAction: [deciderOk('action', action('FILL', 't3'))],
            chooseArgument: [deciderOk('argument', { kind: 'none_appropriate', confidence: 0.99 })],
          },
          { observations: [page()] }
        );
        const paused = requireStatus(await scenario.agent.run(makeRequest()), 'needs_input');
        const before = [...scenario.fakeHost.calls.order];
        const result = requireStatus(
          await scenario.agent.resume({
            checkpoint: paused.checkpoint,
            resolution: { kind: 'inputs', inputs: {} },
            options: invalid,
          }),
          'failed'
        );
        expect(result.error.code).toBe('INVALID_REQUEST');
        expect(scenario.fakeHost.calls.order).toEqual(before);
        return;
      }
      const scenario = setup({}, {}, source === 'configured' ? { run: invalid } : {});
      const result = requireStatus(
        await scenario.agent.run(makeRequest(source === 'request' ? { options: invalid } : {})),
        'failed'
      );
      expect(result.error.code).toBe('INVALID_REQUEST');
      expect(scenario.fakeHost.calls.order).toHaveLength(0);
      expect(scenario.fakeDecider.calls.chooseAction).toHaveLength(0);
    }
  );

  test('cancellation keeps the diagnostics for accepted observations and performs no action', async () => {
    const controller = new AbortController();
    const scenario = setup({
      chooseAction: [
        () => {
          controller.abort();
          return deciderOk('action', action('CLICK', 't1'));
        },
      ],
    });
    const result = requireStatus(
      await scenario.agent.run(
        makeRequest({ options: { captureProgressDiagnostics: true } }),
        controller.signal
      ),
      'cancelled'
    );
    expect(result.progressDiagnostics?.observations).toBe(1);
    expect(result.progressDiagnostics?.semanticChanges).toBe(0);
    expect(scenario.fakeHost.calls.execute).toHaveLength(0);
  });

  test('counts returns to earlier semantic states but bounds retained state history', () => {
    const tracker = progress.createProgressTracker(1);
    const numbered = (number: number) =>
      page({ elements: [makeTextField({ state: { value: String(number) } })] });
    tracker.observe(numbered(0));
    tracker.observe(numbered(1));
    tracker.observe(numbered(0));
    expect(tracker.snapshot().repeatedStates).toBe(1);
    for (const number of [2, 3, 4, 5, 0]) tracker.observe(numbered(number));
    expect(tracker.snapshot().repeatedStates).toBe(1);
    expect(tracker.snapshot().semanticChanges).toBe(7);
    const copy = tracker.snapshot();
    tracker.observe(numbered(0));
    expect(copy.observations).toBe(8);
    expect(tracker.snapshot().observations).toBe(9);
  });

  test.each(['own', 'inherited', 'accessor'] as const)(
    'a %s decider initialization marker fails before all host and model calls',
    async kind => {
      const scenario = setup({});
      const decider = {
        ...scenario.fakeDecider.decider,
        ...(kind === 'own' ? { initializationError: 'INVALID_CONFIGURATION' as const } : {}),
      };
      const getter = jest.fn(() => 'INVALID_CONFIGURATION');
      if (kind === 'inherited') {
        Object.setPrototypeOf(decider, { initializationError: 'INVALID_CONFIGURATION' });
      } else if (kind === 'accessor') {
        Object.defineProperty(decider, 'initializationError', { get: getter });
      }
      const agent = createTaskAgent({ host: scenario.fakeHost.host, decider });
      const result = requireStatus(await agent.run(makeRequest()), 'failed');
      expect(result.error.code).toBe('INVALID_REQUEST');
      expect(result.error.message).toBe('The decider configuration is invalid.');
      expect(scenario.fakeHost.calls.order).toHaveLength(0);
      expect(scenario.fakeDecider.calls.chooseAction).toHaveLength(0);
      expect(getter).not.toHaveBeenCalled();
    }
  );

  test('an invalid custom decider cannot resume a valid checkpoint or release its host', async () => {
    const first = setup(
      {
        chooseAction: [deciderOk('action', action('FILL', 't3'))],
        chooseArgument: [deciderOk('argument', { kind: 'none_appropriate', confidence: 0.99 })],
      },
      { observations: [page()] },
      { checkpointKey: 'test-resume-initialization-marker' }
    );
    const paused = requireStatus(await first.agent.run(makeRequest()), 'needs_input');
    const second = setup({});
    const agent = createTaskAgent({
      host: second.fakeHost.host,
      decider: { ...second.fakeDecider.decider, initializationError: 'INVALID_CONFIGURATION' },
      options: { checkpointKey: 'test-resume-initialization-marker' },
    });
    const result = requireStatus(
      await agent.resume({
        checkpoint: paused.checkpoint,
        resolution: { kind: 'inputs', inputs: {} },
      }),
      'failed'
    );
    expect(result.error.code).toBe('INVALID_REQUEST');
    expect(second.fakeHost.calls.order).toHaveLength(0);
    expect(second.fakeDecider.calls.chooseAction).toHaveLength(0);
  });
});

/** @jest-environment node */
import { createTaskAgent } from '@/agent/TaskAgent';
import type {
  TaskArgumentDecision,
  TaskChooseArgumentRequest,
  TaskDeciderResult,
  TaskRunOptions,
} from '@/types';
import {
  deciderFail,
  deciderOk,
  makeFakeDecider,
  makeFakeHost,
  makeLink,
  makeObservation,
  makeOutcome,
  makeRequest,
  makeSelectField,
} from './helpers/agent-fixtures';
import { action, requireStatus, terminal } from './helpers/task-agent-contract';

type RequirementReply = (
  request: TaskChooseArgumentRequest
) => TaskDeciderResult<TaskArgumentDecision>;

const keep =
  (confidence: number): RequirementReply =>
  () =>
    deciderOk('argument', { kind: 'keep_current', confidence });
const pick =
  (label: string, confidence: number): RequirementReply =>
  request => {
    const candidate = request.candidates.find(item => item.label === label);
    if (!candidate) throw new Error(`The fixture did not offer ${label}`);
    return deciderOk('argument', { kind: 'candidate', candidateId: candidate.id, confidence });
  };

const runScenario = async (
  replies: readonly RequirementReply[],
  settings: {
    readonly scrolls?: number;
    readonly options?: TaskRunOptions;
    readonly uncertainScroll?: boolean;
    readonly signal?: AbortSignal;
  } = {}
) => {
  let current = '1';
  let scrolls = 0;
  const quantity = () =>
    makeSelectField({
      id: 'lamp-quantity',
      label: 'Lamp quantity',
      inputName: 'lamp.quantity',
      landmark: 'main',
      state: { value: current },
      options: ['1', '2', '3'].map(label => ({
        id: `lamp-quantity.${label}`,
        label,
        value: label,
        selected: label === current,
        disabled: false,
      })),
    });
  const observation = () =>
    makeObservation({
      fingerprint: `quantities-view-${scrolls}-${current}`,
      elements: [quantity(), makeLink({ id: 'main', landmark: 'main' })],
      page: {
        readyState: 'complete',
        busy: false,
        scroll: { directions: ['DOWN'], top: scrolls * 100, max: 1000 },
        viewport: { width: 1024, height: 768 },
      },
    });
  const fakeHost = makeFakeHost({ observations: [observation()] });
  const baseObserve = fakeHost.host.observe;
  const baseExecute = fakeHost.host.execute;
  const host = {
    ...fakeHost.host,
    observe: async (...args: Parameters<typeof baseObserve>) => {
      const result = await baseObserve(...args);
      return result.ok
        ? {
            ok: true as const,
            value: {
              ...observation(),
              sessionId: result.value.sessionId,
              snapshotId: result.value.snapshotId,
              sequence: result.value.sequence,
            },
          }
        : result;
    },
    execute: async (...args: Parameters<typeof baseExecute>) => {
      const result = await baseExecute(...args);
      const command = args[0].command;
      if (command.operation === 'SCROLL') {
        scrolls += 1;
        if (settings.uncertainScroll) {
          return makeOutcome('uncertain', 'uncertain', { requestId: args[0].requestId });
        }
      }
      if (command.operation === 'SELECT' && result.effect === 'applied') {
        if (command.optionId === undefined) {
          throw new Error('The fixture requires an exact observed option id');
        }
        const parts = command.optionId.split('.');
        current = parts[parts.length - 1] ?? current;
      }
      return result;
    },
  };
  const requirements: TaskChooseArgumentRequest[] = [];
  const argumentReply: RequirementReply = request => {
    if (request.target?.id === 'lamp-quantity') {
      requirements.push(request);
      const reply = replies[requirements.length - 1];
      if (!reply) return deciderFail('UNSUPPORTED', { retryable: false });
      return reply(request);
    }
    const candidate = request.candidates.find(
      item => item.source === 'protocol' && item.label === 'Scroll DOWN'
    );
    if (!candidate) throw new Error('The fixture did not offer downward scrolling');
    return deciderOk('argument', {
      kind: 'candidate',
      candidateId: candidate.id,
      confidence: 0.99,
    });
  };
  const fakeDecider = makeFakeDecider({
    chooseArgument: Array.from({ length: 20 }, () => argumentReply),
    chooseAction: [
      ...Array.from({ length: settings.scrolls ?? 1 }, () =>
        deciderOk('action', action('SCROLL', 'page'))
      ),
      deciderOk('action', terminal('BLOCKED')),
    ],
    classifyCommitment: Array.from({ length: 10 }, () =>
      deciderOk('commitment', { commitment: 'NONE', confidence: 0.99, agreement: 'single' })
    ),
  });
  const agent = createTaskAgent({
    host,
    decider: { ...fakeDecider.decider, supportsRequirements: true },
  });
  const result = await agent.run(
    makeRequest({
      goal: 'Keep the lamp quantity at one while examining the page.',
      options: {
        captureTrace: true,
        confidence: { argument: 0.3 },
        budgets: { maxModelCalls: 30, maxInvalidDecisions: 0 },
        ...settings.options,
      },
    }),
    settings.signal
  );
  return { result, fakeHost, fakeDecider, requirements, current };
};

describe('requirement rewrite confirmation is local to the current assessment', () => {
  test('an earlier under-floor KEEP_CURRENT resample cannot authorize a later weak rewrite', async () => {
    const { fakeHost, requirements, current } = await runScenario([
      keep(0.28),
      keep(0.28),
      pick('2', 0.34),
      keep(0.7),
    ]);
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual(['SCROLL']);
    expect(current).toBe('1');
    expect(requirements).toHaveLength(4);
    expect(requirements.map(request => request.purpose)).toEqual(Array(4).fill('requirement'));
  });

  test('a current agreeing confirmation permits exactly one rewrite with the original confidence', async () => {
    const { result, fakeHost, requirements, current } = await runScenario([
      keep(0.28),
      keep(0.28),
      pick('2', 0.34),
      pick('2', 0.6),
    ]);
    expect(requirements).toHaveLength(4);
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual([
      'SCROLL',
      'SELECT',
    ]);
    expect(fakeHost.calls.execute[1]?.command).toMatchObject({ optionId: 'lamp-quantity.2' });
    expect(current).toBe('2');
    expect(result.trace?.filter(event => event.type === 'planning')).toEqual([
      expect.objectContaining({ operation: 'SELECT', requirementConfidence: 0.34 }),
    ]);
  });

  test.each([
    ['a different rewrite', pick('3', 0.7)],
    ['an agreeing answer below the floor', pick('2', 0.2)],
    ['an unavailable decider', () => deciderFail('NETWORK')],
    [
      'an explicit uncertain answer',
      () => deciderOk('argument', { kind: 'uncertain_requirement' as const, confidence: 0.7 }),
    ],
  ] as const)('%s cannot leave the first weak rewrite executable', async (_name, second) => {
    const { fakeHost, requirements, current, result } = await runScenario([
      keep(0.28),
      keep(0.28),
      pick('2', 0.34),
      second,
    ]);
    expect(requirements).toHaveLength(4);
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual(['SCROLL']);
    expect(current).toBe('1');
    expect(result.status).not.toBe('completed');
  });

  test('a weak rewrite with an unavailable second answer fails closed on its first assessment', async () => {
    const { fakeHost, requirements, current } = await runScenario(
      [pick('2', 0.34), () => deciderFail('NETWORK')],
      { scrolls: 0 }
    );
    expect(fakeHost.calls.execute).toHaveLength(0);
    expect(current).toBe('1');
    expect(requirements).toHaveLength(2);
  });

  test('each uncached reassessment requires confirmation after real page progress', async () => {
    const { fakeHost, requirements, current } = await runScenario(
      [keep(0.28), keep(0.28), pick('2', 0.34), pick('3', 0.7), pick('2', 0.34), keep(0.7)],
      { scrolls: 2 }
    );
    expect(requirements).toHaveLength(6);
    expect(requirements[2]?.observation.documentId).toBe(requirements[4]?.observation.documentId);
    expect(requirements[2]?.observation.fingerprint).not.toBe(
      requirements[4]?.observation.fingerprint
    );
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual([
      'SCROLL',
      'SCROLL',
    ]);
    expect(current).toBe('1');
  });

  test('generic under-floor judgments retain their one-resample limit for the field and document', async () => {
    const { fakeHost, requirements, current } = await runScenario([
      keep(0.28),
      keep(0.28),
      keep(0.28),
      pick('2', 0.7),
    ]);
    expect(requirements).toHaveLength(3);
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual(['SCROLL']);
    expect(current).toBe('1');
  });

  test('a mandatory confirmation still obeys the model-call budget before making its second call', async () => {
    const { result, fakeHost, requirements, current } = await runScenario(
      [pick('2', 0.34), pick('2', 0.7)],
      { scrolls: 0, options: { budgets: { maxModelCalls: 1 } } }
    );
    expect(requireStatus(result, 'blocked').budget).toBe('maxModelCalls');
    expect(result.stats.usage.modelCalls).toBe(1);
    expect(requirements).toHaveLength(1);
    expect(fakeHost.calls.execute).toHaveLength(0);
    expect(current).toBe('1');
  });

  test('an exhausted decider-failure budget preserves its terminal failure', async () => {
    const { result, fakeHost, requirements, current } = await runScenario(
      [pick('2', 0.34), () => deciderFail('NETWORK')],
      { scrolls: 0, options: { budgets: { maxDeciderFailures: 0 } } }
    );
    expect(requireStatus(result, 'failed').error.code).toBe('DECIDER_FAILED');
    expect(result.stats.usage.deciderFailures).toBe(1);
    expect(requirements).toHaveLength(2);
    expect(fakeHost.calls.execute).toHaveLength(0);
    expect(current).toBe('1');
  });

  test.each(['first', 'confirmation'] as const)(
    'cancellation during the %s sample never executes the weak rewrite',
    async cancellationStage => {
      const controller = new AbortController();
      const abortingPick: RequirementReply = request => {
        controller.abort();
        return pick('2', 0.34)(request);
      };
      const replies =
        cancellationStage === 'first'
          ? [abortingPick, pick('2', 0.7)]
          : [pick('2', 0.34), abortingPick];
      const { result, fakeHost, requirements, current } = await runScenario(replies, {
        scrolls: 0,
        signal: controller.signal,
      });
      expect(result.status).toBe('cancelled');
      expect(requirements).toHaveLength(cancellationStage === 'first' ? 1 : 2);
      expect(fakeHost.calls.execute).toHaveLength(0);
      expect(current).toBe('1');
    }
  );

  test('uncertain page progress cannot authorize a new weak rewrite or repeat the scroll', async () => {
    const { result, fakeHost, requirements, current } = await runScenario(
      [keep(0.28), keep(0.28), pick('2', 0.34), pick('2', 0.7)],
      { scrolls: 2, uncertainScroll: true, options: { budgets: { maxUncertainEffects: 0 } } }
    );
    expect(requireStatus(result, 'blocked').reason).toBe('UNCERTAIN_EFFECT');
    expect(requirements).toHaveLength(2);
    expect(fakeHost.calls.execute.map(request => request.command.operation)).toEqual(['SCROLL']);
    expect(current).toBe('1');
  });
});

/** @jest-environment node */
import { randomUUID } from 'crypto';
import {
  assertGoalPreserved,
  buildArgumentQuestions,
  estimateRequestBytes,
  questionRotations,
} from '@/agent/request';
import { createTypeSafeTaskDecider } from '@/agent/typesafe';
import {
  TASK_KEEP_CURRENT,
  TASK_LIMITS,
  TASK_NONE_APPROPRIATE,
  TASK_REDACTED,
  TASK_REQUIRED_UNAVAILABLE,
  TASK_UNTRUSTED_DATA_RULE,
} from '@/types';
import type {
  TaskArgumentDecision,
  TaskChooseArgumentRequest,
  TaskHttp,
  TaskQuestionSet,
  TypeSafeTaskDeciderConfig,
} from '@/types';
import {
  makeCheckbox,
  makeObservation,
  makeSensitiveField,
  makeTextField,
} from './helpers/agent-fixtures';

const GOAL = 'Keep the existing details unchanged — café.\nUse only supplied data.';
const SENTINELS = [TASK_KEEP_CURRENT, TASK_REQUIRED_UNAVAILABLE, TASK_NONE_APPROPRIATE];
const ASSESSED_PURPOSES = ['requirement', 'validation', 'group'] as const;
type AssessedPurpose = (typeof ASSESSED_PURPOSES)[number];

const requestFor = (
  purpose?: TaskChooseArgumentRequest['purpose'],
  overrides: Partial<TaskChooseArgumentRequest> = {}
): TaskChooseArgumentRequest => {
  const target = makeTextField({ state: { value: 'Observed existing detail' } });
  return {
    goal: GOAL,
    step: 0,
    ...(purpose === undefined ? {} : { purpose }),
    target,
    observation: makeObservation({ elements: [target] }),
    operation: 'FILL',
    slot: 'value',
    candidates: [],
    inputs: [],
    history: [],
    maxStateBytes: TASK_LIMITS.modelStateBytes,
    ...overrides,
  };
};

const argumentKeys = (set: TaskQuestionSet): string[] =>
  Object.keys(set.questions['argument']?.criteria ?? {});

const harness = (
  choices: Readonly<Record<string, string>>,
  overrides: Partial<TypeSafeTaskDeciderConfig> = {}
) => {
  const sent: TaskQuestionSet[] = [];
  const bodies: string[] = [];
  const http: TaskHttp = (_url, init) => {
    const body = JSON.parse(init.body) as TaskQuestionSet;
    sent.push(body);
    bodies.push(init.body);
    const answers = Object.fromEntries(
      Object.entries(body.questions).map(([key, question]) => {
        const choice = choices[key];
        expect(choice).toBeDefined();
        expect(Object.keys(question.criteria)).toContain(choice);
        return [
          key,
          {
            type: 'choice',
            choice,
            confidence: key === 'argument_applicability' ? 0.91 : 0.63,
            probabilities: Object.fromEntries(
              Object.keys(question.criteria).map(option => [option, option === choice ? 1 : 0])
            ),
          },
        ];
      })
    );
    return Promise.resolve({
      ok: true,
      status: 200,
      header: () => null,
      json: () => Promise.resolve({ model: 'jev-1.13.0', answers }),
    });
  };
  const decider = createTypeSafeTaskDecider({
    apiKey: `test-${randomUUID()}`,
    http,
    ...overrides,
  });
  const choose = (request: TaskChooseArgumentRequest) =>
    decider.chooseArgument(request, {
      goal: request.goal,
      step: request.step,
      runId: 'run_000000000001',
      callIndex: 1,
    });
  return { sent, bodies, choose };
};

describe('empty semantic candidate assessments', () => {
  it.each(ASSESSED_PURPOSES)('keeps semantic choices and literal goal for %s', purpose => {
    for (const step of [0, 1, 5]) {
      for (const rotate of [true, false]) {
        const set = buildArgumentQuestions(requestFor(purpose, { step }), { rotate });
        expect(argumentKeys(set)).toEqual(SENTINELS);
        expect(Object.keys(set.questions)).toEqual(
          purpose === 'group' ? ['argument'] : ['argument_applicability', 'argument']
        );
        expect(assertGoalPreserved(set, GOAL)).toEqual({ ok: true });
        expect(set.state.focus?.value).toBe('Observed existing detail');
        for (const question of Object.values(set.questions)) {
          expect(question.type).toBe('choice');
          expect(Object.keys(question.criteria).length).toBeGreaterThanOrEqual(2);
          expect(question.instructions['rules']).toContain(TASK_UNTRUSTED_DATA_RULE);
        }
        expect(questionRotations(set, step, rotate)['argument']).toBe(0);
      }
    }
  });

  const outcomes: readonly {
    readonly purpose: AssessedPurpose;
    readonly choice: string;
    readonly kind: TaskArgumentDecision['kind'];
  }[] = ASSESSED_PURPOSES.flatMap(purpose => [
    { purpose, choice: TASK_KEEP_CURRENT, kind: 'keep_current' as const },
    { purpose, choice: TASK_REQUIRED_UNAVAILABLE, kind: 'required_unavailable' as const },
    {
      purpose,
      choice: TASK_NONE_APPROPRIATE,
      kind: purpose === 'group' ? ('none_appropriate' as const) : ('required_unavailable' as const),
    },
  ]);

  it.each(outcomes)('roundtrips $purpose / $choice through the adapter', async entry => {
    const fake = harness({ argument_applicability: 'REQUIRED', argument: entry.choice });
    const result = await fake.choose(requestFor(entry.purpose));
    expect(result.ok).toBe(true);
    if (result.ok) {
      expect(result.decision).toEqual({ kind: entry.kind, confidence: 0.63 });
      expect(result.exchange.goalVerified).toBe(true);
      expect(result.exchange.rotations?.['argument']).toBe(0);
    }
    expect(fake.sent).toHaveLength(1);
    expect(argumentKeys(fake.sent[0] as TaskQuestionSet)).toEqual(SENTINELS);
    expect(fake.sent[0]?.state.task).toBe(GOAL);
  });

  it.each(['requirement', 'validation'] as const)(
    'retains unrelated and uncertain applicability semantics for %s',
    async purpose => {
      for (const [applicability, kind] of [
        ['UNRELATED', 'none_appropriate'],
        ['UNCERTAIN', 'uncertain_requirement'],
      ] as const) {
        const fake = harness({
          argument_applicability: applicability,
          argument: TASK_REQUIRED_UNAVAILABLE,
        });
        const result = await fake.choose(requestFor(purpose));
        expect(result.ok).toBe(true);
        if (result.ok) {
          expect(result.decision).toEqual({ kind, confidence: 0.91 });
        }
        expect(fake.sent).toHaveLength(1);
      }
    }
  );

  it('preserves real observed group context without inventing member candidates', async () => {
    const members = [
      makeCheckbox({ kind: 'radio', role: 'radio', state: { checked: true } }),
      makeCheckbox({ id: 't24', kind: 'radio', role: 'radio', state: { checked: false } }),
    ];
    const request = requestFor('group', {
      target: members[0],
      operation: 'SET_CHECKED',
      slot: 'checked',
      group: { id: 'observed_group', members },
      observation: makeObservation({ elements: members }),
    });
    const fake = harness({ argument: TASK_KEEP_CURRENT });
    const result = await fake.choose(request);
    expect(result.ok).toBe(true);
    expect(fake.sent[0]?.state.group?.members.map(member => member.id)).toEqual(
      members.map(member => member.id)
    );
    expect(fake.sent[0]?.state.group?.members[0]?.checked).toBe(true);
    expect(argumentKeys(fake.sent[0] as TaskQuestionSet)).toEqual(SENTINELS);
    expect(fake.sent[0]?.questions['argument']?.instructions['rules']).toContain(
      'Choose the single desired member of the mutually exclusive group in state.group.'
    );
  });

  it('keeps an empty sensitive field opaque through a real adapter call', async () => {
    const opaque = `runtime-${randomUUID()}`;
    const target = makeSensitiveField({ state: { value: opaque } });
    const request = requestFor('requirement', {
      target,
      observation: makeObservation({ elements: [target] }),
      inputs: [{ path: 'profile.password', description: 'Existing credential', sensitive: true }],
    });
    const fake = harness({ argument_applicability: 'REQUIRED', argument: TASK_KEEP_CURRENT });
    const result = await fake.choose(request);
    expect(result.ok).toBe(true);
    expect(fake.sent).toHaveLength(1);
    expect(fake.sent[0]?.state.focus?.value).toBe(TASK_REDACTED);
    expect(fake.bodies[0]).not.toContain(opaque);
    expect(fake.sent[0]?.state.inputs[0]).toEqual(request.inputs[0]);
  });
});

describe('candidate compatibility and budgets', () => {
  it.each([undefined, 'activation'] as const)(
    'deliberately refuses an empty non-assessed %s request before HTTP',
    async purpose => {
      const request = requestFor(purpose);
      expect(buildArgumentQuestions(request).questions).toEqual({});
      const fake = harness({});
      const result = await fake.choose(request);
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.error.code).toBe('INVALID_REQUEST');
        expect(result.error.retryable).toBe(false);
      }
      expect(fake.sent).toHaveLength(0);
    }
  );

  it.each([undefined, 'requirement', 'validation', 'activation', 'group'] as const)(
    'preserves offered ids, first-option rotation and candidate parsing for %s',
    async purpose => {
      const candidates = ['c1', 'c2', 'c3'].map(id => ({
        id,
        source: 'input' as const,
        inputPath: `profile.${id}`,
        label: `Supplied detail ${id}`,
        preview: `Value ${id}`,
        sensitive: false,
      }));
      const request = requestFor(purpose, { candidates, step: 1 });
      const assessed = purpose !== undefined && purpose !== 'activation';
      const applicability = purpose !== undefined && purpose !== 'group';
      const set = buildArgumentQuestions(request);
      expect(argumentKeys(set)).toEqual([
        ...(applicability ? ['c3', 'c1', 'c2'] : ['c2', 'c3', 'c1']),
        ...(assessed ? SENTINELS : [TASK_NONE_APPROPRIATE]),
      ]);
      const fake = harness({ argument_applicability: 'REQUIRED', argument: 'c2' });
      const result = await fake.choose(request);
      expect(result.ok).toBe(true);
      if (result.ok) {
        expect(result.decision).toEqual({ kind: 'candidate', candidateId: 'c2', confidence: 0.63 });
      }
      expect(fake.sent).toHaveLength(1);
    }
  );

  it.each(ASSESSED_PURPOSES)(
    'keeps %s sentinels when the byte budget cannot fit and refuses before HTTP',
    async purpose => {
      const request = requestFor(purpose);
      const set = buildArgumentQuestions(request, { maxRequestBytes: 1 });
      expect(argumentKeys(set)).toEqual(SENTINELS);
      expect(assertGoalPreserved(set, GOAL)).toEqual({ ok: true });
      expect(estimateRequestBytes(set, 'jev-latest')).toBeGreaterThan(1);
      const fake = harness({}, { maxRequestBytes: 1 });
      const result = await fake.choose(request);
      expect(result.ok).toBe(false);
      if (!result.ok) {
        expect(result.error.code).toBe('REQUEST_TOO_LARGE');
      }
      expect(fake.sent).toHaveLength(0);
    }
  );

  it.each(['requirement', 'validation'] as const)(
    'refuses oversized %s supplied data instead of manufacturing its absence',
    async purpose => {
      const request = requestFor(purpose, {
        candidates: Array.from({ length: 20 }, (_, index) => ({
          id: `c${String(index)}`,
          source: 'goal_span' as const,
          label: 'Observed offered detail '.repeat(20),
          preview: 'Supplied literal value '.repeat(20),
          sensitive: false,
        })),
      });
      const empty = buildArgumentQuestions({ ...request, candidates: [] }, { maxRequestBytes: 1 });
      const maxRequestBytes = estimateRequestBytes(empty, 'm'.repeat(64));
      const set = buildArgumentQuestions(request, { maxRequestBytes });
      expect(argumentKeys(set)).toEqual(['c0', ...SENTINELS]);
      expect(estimateRequestBytes(set, 'm'.repeat(64))).toBeGreaterThan(maxRequestBytes);
      const fake = harness(
        { argument_applicability: 'REQUIRED', argument: TASK_KEEP_CURRENT },
        { maxRequestBytes }
      );
      const result = await fake.choose(request);
      expect(result.ok).toBe(false);
      if (result.ok) {
        throw new Error('expected oversized request refusal');
      }
      expect(result.error.code).toBe('REQUEST_TOO_LARGE');
      expect(fake.sent).toHaveLength(0);
    }
  );
});

