            ok: true,
            operation: 'HIGHLIGHT',
            targetIndex: target(request, 'HIGHLIGHT', 'Recurring'),
            confidence: 1,
          };
        expect(target(request, 'HIGHLIGHT', 'Recurring')).toBe('');
        return finishYes;
      }
    );
    expect(result.ok).toBe(true);
